"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


_STAR = object()


@dataclass(frozen=True)
class _Pattern:
    negate: bool
    dir_only: bool
    anchored: bool
    # Anchored: one entry per path segment, None meaning a `**` segment.
    # Basename: a single token list matched against the last path segment.
    parts: tuple[list | None, ...]


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""
    compiled = [pat for pat in map(_parse_line, patterns) if pat is not None]
    segments = path.split("/")
    basename = segments[-1]

    ignored = False
    for pat in compiled:
        if pat.dir_only and not is_dir:
            continue
        if pat.anchored:
            matched = _match_segments(pat.parts, segments)
        else:
            matched = _match_tokens(pat.parts[0], basename)
        if matched:
            ignored = not pat.negate
    return ignored


def _parse_line(line: str) -> _Pattern | None:
    line = _strip_trailing_spaces(line)
    if not line or line.startswith("#"):
        return None

    negate = line.startswith("!")
    if negate:
        line = line[1:]

    dir_only = line.endswith("/")
    if dir_only:
        line = line[:-1]
    if not line:
        return None

    if "/" in line:
        if line.startswith("/"):
            line = line[1:]
        segments = line.split("/")
        parts = tuple(
            None if seg == "**" and len(segments) > 1 else _compile_segment(seg)
            for seg in segments
        )
        return _Pattern(negate, dir_only, True, parts)

    return _Pattern(negate, dir_only, False, (_compile_segment(line),))


def _strip_trailing_spaces(line: str) -> str:
    while line.endswith(" "):
        head = line[:-1]
        backslashes = len(head) - len(head.rstrip("\\"))
        if backslashes % 2:
            break
        line = head
    return line


def _compile_segment(seg: str) -> list:
    tokens: list = []
    i = 0
    while i < len(seg):
        ch = seg[i]
        if ch == "*":
            tokens.append(_STAR)
            i += 1
        elif ch == "?":
            tokens.append(_any_char)
            i += 1
        elif ch == "[":
            pred, i = _compile_class(seg, i + 1)
            tokens.append(pred)
        elif ch == "\\":
            literal, i = _class_char(seg, i)
            tokens.append(_literal(literal))
        else:
            tokens.append(_literal(ch))
            i += 1
    return tokens


def _compile_class(seg: str, i: int) -> tuple[Callable[[str], bool], int]:
    negate = i < len(seg) and seg[i] == "!"
    if negate:
        i += 1

    ranges: list[tuple[str, str]] = []
    first = True
    while True:
        if i >= len(seg):
            raise PatternError(f"unterminated character class in {seg!r}")
        if seg[i] == "]" and not first:
            i += 1
            break
        first = False

        lo, i = _class_char(seg, i)
        hi = lo
        if i + 1 < len(seg) and seg[i] == "-" and seg[i + 1] != "]":
            hi, i = _class_char(seg, i + 1)
            if hi < lo:
                raise PatternError(f"reversed character range in {seg!r}")
        ranges.append((lo, hi))

    def predicate(ch: str) -> bool:
        return any(lo <= ch <= hi for lo, hi in ranges) != negate

    return predicate, i


def _class_char(seg: str, i: int) -> tuple[str, int]:
    if seg[i] != "\\":
        return seg[i], i + 1
    if i + 1 >= len(seg):
        raise PatternError(f"dangling backslash in {seg!r}")
    return seg[i + 1], i + 2


def _literal(expected: str) -> Callable[[str], bool]:
    def predicate(ch: str) -> bool:
        return ch == expected

    return predicate


def _any_char(ch: str) -> bool:
    return True


def _match_tokens(tokens: list, text: str) -> bool:
    n = len(text)
    positions = {0}
    for tok in tokens:
        if tok is _STAR:
            positions = set(range(min(positions), n + 1))
        else:
            positions = {p + 1 for p in positions if p < n and tok(text[p])}
        if not positions:
            return False
    return n in positions


def _match_segments(parts: tuple[list | None, ...], segments: list[str]) -> bool:
    memo: dict[tuple[int, int], bool] = {}

    def go(pi: int, si: int) -> bool:
        key = (pi, si)
        if key not in memo:
            memo[key] = _go(pi, si)
        return memo[key]

    def _go(pi: int, si: int) -> bool:
        if pi == len(parts):
            return si == len(segments)
        part = parts[pi]
        if part is None:
            if pi == len(parts) - 1:
                return si < len(segments)
            return any(go(pi + 1, k) for k in range(si, len(segments) + 1))
        return si < len(segments) and _match_tokens(part, segments[si]) and go(pi + 1, si + 1)

    return go(0, 0)
